import{_ as t,o as e,c as i,a2 as d}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"run","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/cli/run.md","filePath":"zh-CN/cli/run.md","lastUpdated":1784903584000}'),l={name:"zh-CN/cli/run.md"};function r(o,a,s,n,h,c){return e(),i("div",null,[...a[0]||(a[0]=[d('<h1 id="run" tabindex="-1">run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;run&quot;">​</a></h1><h2 id="用途" tabindex="-1">用途 <a class="header-anchor" href="#用途" aria-label="Permalink to &quot;用途&quot;">​</a></h2><p>启动交互式 <strong>TUI（终端用户界面）</strong> API 浏览器。这是一个全屏应用程序，用于搜索、浏览、检查和调用 API 端点，无需离开终端。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>你想交互式地探索你的 API</li><li>你需要跨所有 spec 搜索特定端点</li><li>你想浏览 spec → collection → tag → endpoint 层次结构</li><li>你想在配置 MCP 服务器之前测试 API 调用</li></ul><h2 id="语法" tabindex="-1">语法 <a class="header-anchor" href="#语法" aria-label="Permalink to &quot;语法&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [path]</span></span></code></pre></div><h2 id="参数" tabindex="-1">参数 <a class="header-anchor" href="#参数" aria-label="Permalink to &quot;参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>位置</th><th>必需</th><th>描述</th></tr></thead><tbody><tr><td><code>path</code></td><td>1</td><td>否</td><td>工作区目录。如果省略，通过路径解析规则解析。</td></tr></tbody></table><h2 id="标志" tabindex="-1">标志 <a class="header-anchor" href="#标志" aria-label="Permalink to &quot;标志&quot;">​</a></h2><p>无。</p><h2 id="模式" tabindex="-1">模式 <a class="header-anchor" href="#模式" aria-label="Permalink to &quot;模式&quot;">​</a></h2><h3 id="搜索模式" tabindex="-1">搜索模式 <a class="header-anchor" href="#搜索模式" aria-label="Permalink to &quot;搜索模式&quot;">​</a></h3><p>跨所有 spec 中所有端点的全文搜索。支持按 HTTP 方法、标签和路径过滤。</p><ul><li>输入查询以搜索端点名称、路径和描述</li><li>按方法过滤结果（GET、POST、PUT、DELETE 等）</li><li>一键查看端点详情</li></ul><h3 id="浏览模式" tabindex="-1">浏览模式 <a class="header-anchor" href="#浏览模式" aria-label="Permalink to &quot;浏览模式&quot;">​</a></h3><p>通过 spec 层次结构进行树形导航：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Spec → Collection → Tag → Endpoint</span></span></code></pre></div><ul><li>向下导航树以查找特定端点</li><li>查看端点详情（参数、请求体、响应）</li><li>直接从 TUI 调用 API</li></ul><h2 id="导航" tabindex="-1">导航 <a class="header-anchor" href="#导航" aria-label="Permalink to &quot;导航&quot;">​</a></h2><table tabindex="0"><thead><tr><th>按键</th><th>操作</th></tr></thead><tbody><tr><td><code>↑</code> / <code>↓</code></td><td>向上/向下导航</td></tr><tr><td><code>Enter</code></td><td>选择或打开</td></tr><tr><td><code>Esc</code></td><td>返回</td></tr><tr><td><code>Tab</code></td><td>在搜索和浏览模式之间切换</td></tr><tr><td><code>/</code></td><td>聚焦搜索输入</td></tr><tr><td><code>q</code></td><td>退出</td></tr></tbody></table><h2 id="命令后验证" tabindex="-1">命令后验证 <a class="header-anchor" href="#命令后验证" aria-label="Permalink to &quot;命令后验证&quot;">​</a></h2><p>TUI 从工作区加载所有 spec。如果 spec 加载失败，界面中会显示错误消息。</p><h2 id="细节" tabindex="-1">细节 <a class="header-anchor" href="#细节" aria-label="Permalink to &quot;细节&quot;">​</a></h2><ul><li><strong>自动初始化：</strong> 如果不存在配置文件，<code>run</code> 会自动先运行初始化向导。</li><li><strong>无标志：</strong> <code>run</code> 命令没有标志 — 所有配置来自工作区。</li><li><strong>终端大小：</strong> TUI 需要至少 80×24 字符的终端。在非常小的终端中可能无法正确渲染。</li><li><strong>依赖：</strong> TUI 使用 Bubbletea。它可以通过 SSH 和在大多数终端模拟器中工作。</li></ul>',25)])])}const b=t(l,[["render",r]]);export{u as __pageData,b as default};
